"""A chapter 3: every choice, fill, judgment and short response."""
from qd1000_next_common import *

def q(n,o,qp,ap,stem,options,ans,exp,topic='时域分析 / 响应'):
    return C(3,'选择题',n,o,qp,ap,stem+'\n\n'+'\n\n'.join(f'{chr(65+i)}. {v}' for i,v in enumerate(options)),ans,exp,topic)
def f(n,o,qp,ap,stem,ans,exp,topic='时域分析 / 响应',notes=''):
    return C(3,'填空题',n,o,qp,ap,stem,ans,exp,topic,notes)
def j(n,o,qp,ap,stem,ans,exp):return C(3,'判断题',n,o,qp,ap,'判断正误：'+stem,ans,exp,'时域分析 / 基本响应')
def sh(n,o,qp,ap,stem,ans,exp):return C(3,'简答题',n,o,qp,ap,stem,ans,exp,'时域分析 / 二阶性能')

q(1,'北京交通大学 2025','54','102',r'单位负反馈开环传递函数 $G=K/[s(s+1)(s+5)]$。闭环渐近稳定时 $K$ 的范围为：',
  ['$0<K<5$','$0<K<15$','$0<K<30$','$0<K<40$'],'C。$0<K<30$。',
  r'特征多项式为 $D=s^3+6s^2+5s+K$。三阶劳斯首列为 $1,6,(30-K)/6,K$。首列同正要求 $K>0$ 且 $30-K>0$，因此选 C；边界 $K=0$ 或 $K=30$ 都不属于渐近稳定。','时域分析 / 劳斯稳定')
q(2,'北京交通大学 2025','54','102',r'单位负反馈开环 $G=K/[s(s+2)]$，$K>1$。按典型二阶系统的 $t_s\approx3/(\zeta\omega_n)$ 估算，增大 $K$ 时调节时间和超调量如何变化？',
 ['前者下降，后者上升','前者不变，后者上升','都下降','前者不变，后者下降'],'B。',
 r'闭环分母 $s^2+2s+K$，故 $\omega_n=\sqrt K$、$\zeta=1/\sqrt K$，乘积 $\zeta\omega_n=1$。因此 5% 工程估算 $t_s\approx3$ 不变。相对超调量 $\exp[-\pi/\sqrt{K-1}]$ 随 $K$ 增大而增大。这里“不变”针对题干指定的工程估算，实际最后进入误差带的时刻会随振荡相位变化。','时域分析 / 二阶性能')
q(3,'北京交通大学 2025','54','102–103',r'无零点的典型二阶系统，闭环极点为 $-1\pm j$。单位阶跃下的 5% 调节时间按 $3/(\zeta\omega_n)$ 估算，求 $t_s,t_p$。',
 ['$3,\pi$','$4,\pi$','$3,3\pi/4$','$4,3\pi/4$'],r'A。$t_s\approx3\,\mathrm s,t_p=\pi\,\mathrm s$。',
 r'极点形式 $-\zeta\omega_n\pm j\omega_d$，故 $\zeta\omega_n=1$、$\omega_d=1$。峰值时间为 $\pi/\omega_d=\pi$，5% 调节时间的常用工程值为 $3/(\zeta\omega_n)=3$。','时域分析 / 二阶性能')
q(4,'北京交通大学 2015','54–55','103',r'一阶系统闭环传递函数 $1/(s+1)$，零初值，输入 $r(t)=2\,1(t)$。求 2% 调节时间的常用近似值。',
 ['$3\,\mathrm s$','$4\,\mathrm s$','$6\,\mathrm s$','$8\,\mathrm s$'],'B。约 $4\,\mathrm s$。',
 r'输出 $c(t)=2(1-e^{-t})$，相对误差为 $e^{-t}$。精确阈值由 $e^{-t_s}=0.02$ 得 $t_s=\ln50\approx3.912\,\mathrm s$，工程上取 $4T=4\,\mathrm s$。输入幅度改变不会改变相对误差带对应的时间。','时域分析 / 一阶响应')
q(5,'电子科技大学（862）2025','55','103',r'稳定的 0 型单位负反馈系统，在前向通道串联常数增益 $0<K<1$，且串联后仍稳定。仅从静态跟踪误差看，其影响是：',
 ['系统型别增加','稳态精度提高','稳态精度下降','稳态精度不变'],'C。',
 r'设原位置误差系数为 $K_p>0$，单位阶跃稳态误差为 $1/(1+K_p)$。串联后变为 $1/(1+KK_p)$，因 $0<K<1$，误差增大。常数比例环节没有增加积分器，系统型别不变。扰动抑制还取决于扰动注入位置，本题不把它作为与静态误差并列的另一正确选项。','时域分析 / 稳态误差')['notes']='原选择题关于抗干扰能力的选项缺少扰动位置约定；题面收束为稳定0型系统的静态跟踪精度，消除多解歧义。'
q(6,'电子科技大学（862）2025','55','103',r'关于稳定系统闭环主导极点的常用工程判断，下列错误的是：',
 ['其他极点距虚轴的距离通常至少约为主导极点的五倍','应与其他极点充分分离，且附近没有导致近似相消的零点','所对应模态衰减相对缓慢','主导极点必须位于 $s=-1$ 左侧'],'D。',
 r'主导极点的关键是相对于其他模态衰减得慢、且留数不可忽略。若为简单极点 $p=-a+jb$，其模态包络为 $e^{-at}$；$a$ 相对较小才可能主导。是否位于 $-1$ 左侧随时间单位改变而改变，不能作为必要条件。五倍规则是工程近似，不能替代零极点和留数检查。','时域分析 / 主导极点')['notes']='纠正原A项五倍距离的比较方向，并将绝对距离措辞改为相对衰减条件。'
q(7,'电子科技大学（862）2025','55','103–104',r'单位负反馈开环 $G=2/[s(0.2s+1)(s+1)]$，输入为单位斜坡，求稳态误差。',
 ['$0.1$','$0.2$','$0.3$','$0.5$'],'D。$0.5$。',
 r'先判稳：特征多项式为 $0.2s^3+1.2s^2+s+2$，三阶条件 $1.2\times1>0.2\times2$ 成立。速度误差系数 $K_v=\lim_{s\to0}sG(s)=2$，因此 $e_{ss}=1/K_v=0.5$。','时域分析 / 稳态误差')
q(8,'电子科技大学（862）2025','55','104',r'一阶系统 $K_0/(Ts+1)$ 的时间常数 $T>0$ 增大，给定相同相对误差带后，调节时间如何变化？',
 ['变长','不变','变短','不能判断'],'A。',
 r'一阶阶跃响应的相对剩余误差为 $e^{-t/T}$。误差带为 $\delta$ 时，$t_s=-T\ln\delta$，与 $T$ 成正比。故时间常数越大，响应越慢，达到相同精度所需时间越长。','时域分析 / 一阶响应')
q(9,'电子科技大学（862）2025','55','104',r'单位负反馈开环 $G=10(s+1)/[s(s-1)(s+5)]$，闭环系统属于：',
 ['稳定','条件稳定','临界稳定','不稳定'],'A。',
 r'开环有右半平面极点并不直接决定闭环稳定性。闭环特征多项式为 $s(s-1)(s+5)+10(s+1)=s^3+4s^2+5s+10$。劳斯首列为 $1,4,5/2,10$，全部为正，因此闭环渐近稳定。','时域分析 / 劳斯稳定')
q(10,'东华大学 2025','56','105',r'系统闭环传递函数 $5/[(s^2+2s+4)(s+36)]$。按主导二阶模型求近似峰值时间。',
 ['$\pi/\sqrt3\,\mathrm s$',r'$(\pi-\arccos0.5)/\sqrt3\,\mathrm s$','$3\,\mathrm s$','$4\,\mathrm s$'],'A。',
 r'闭环极点为 $-1\pm j\sqrt3$ 与 $-36$。快极点远离主导极点，保留静态增益后近似为 $[5/36]/(s^2+2s+4)$。其阻尼振荡频率为 $\sqrt3$，故 $t_p\approx\pi/\sqrt3$。分子常数影响幅值，不影响典型二阶峰值时间。B 是上升时间公式。','时域分析 / 主导极点')
q(11,'东华大学 2025','56','105',r'开环 $G=30/[(3s+2)(s+5)(2s+3)]$。将各非积分因子写成 $Ts+1$ 形式，开环增益为：',
 ['2','1','3','-1'],'B。$K=1$。',
 r'分别提取三个常数 $2,5,3$，分母总常数为 $30$。因此 $G=1/[(1.5s+1)(0.2s+1)((2/3)s+1)]$，时间常数形式的增益为 $30/(2\cdot5\cdot3)=1$。不要把最高次系数归一形式中的系数当成开环静态增益。','建模 / 传递函数')
q(12,'杭州电子科技大学 2025','56','105–106',r'高阶稳定系统的闭环主导极点向虚轴靠近，且主导关系与留数不发生显著变化，则响应的衰减速度：',
 ['一定振荡更大','一定振荡更小','更快','更慢'],'D。',
 r'设主导极点 $p=-a+jb$，$a>0$。相应模态含 $e^{-at}\cos(bt+\varphi)$，其包络衰减时间常数为 $1/a$。向虚轴靠近意味着 $a$ 减小，因此衰减变慢，调节过程通常延长。仅凭与虚轴的距离不能断定振荡频率或超调量的变化。','时域分析 / 主导极点')
q(13,'杭州电子科技大学 2025','56','106',r'零初值，闭环传递函数 $\Phi=4/(s^2+2s+4)$。定义 $e=r-c$，输入单位斜坡，求稳态误差。',
 ['$1/2$','$1$','$0$','$\infty$'],'A。$1/2$。',
 r'误差变换为 $E=(1-\Phi)/s^2=(s+2)/[s(s^2+2s+4)]$。$sE$ 的极点均在左半平面，终值定理适用，因此 $e_{ss}=\lim_{s\to0}(s+2)/(s^2+2s+4)=1/2$。题给的是闭环传递函数，不能直接把它代入开环速度误差系数。','时域分析 / 稳态误差')
q(14,'北方工业大学 2025','56','106–107',r'从以下开环传递函数中选出 II 型系统，并检验：接单位负反馈后是否稳定、能否实际无差跟踪单位斜坡？',
 ['$1/(s+1)$','$1/[s(s+1)]$','$1/[s(s+2)]$','$1/[s^2(s+2)]$'],'D 为 II 型，但闭环不稳定，不能实际无差跟踪斜坡；本题给出的四个系统均不能稳定地无差跟踪斜坡。',
 r'A 为 0 型，B、C 为 I 型，D 有两个未相消原点极点，所以 D 为 II 型。D 的闭环特征式为 $s^3+2s^2+1$，劳斯首列 $1,2,-1/2,1$ 有两次变号，故不稳定。形式上的 $K_v=\infty$ 不能代替稳定性前提。稳定的 II 型单位负反馈系统才具有零斜坡稳态误差。','时域分析 / 稳态误差')['notes']='原题直接问“能够无差跟踪斜坡”但D对应不稳定闭环，8月勘误未列此项；保留四个原传递函数，改为先辨型再判稳的完整问题。'
q(15,'昆明理工大学 2025','56','107',r'稳定系统主导极点离虚轴越近，其他模态贡献不显著变化时，响应衰减速度如何变化？',
 ['不变','变快','只由输入幅度决定','变慢'],'D。',
 r'稳定极点实部为 $-a$，模态衰减因子为 $e^{-at}$。极点向虚轴靠近即 $a$ 减小，其衰减时间常数 $1/a$ 增大，所以响应变慢。该判断依据负实部的绝对值，而不是极点模长。','时域分析 / 主导极点')
q(16,'昆明理工大学 2025','57','107',r'同一被控对象、同一可检测扰动，在反馈与前馈均正确设计的常规比较下，以下哪种结构缺少自动抑制该扰动的通道，因而通常受其影响最大？',
 ['复合控制','反馈控制','仅按给定量的开环控制','按已测扰动量的前馈控制'],'C。',
 r'仅按给定量的开环控制不测输出偏差，也不测扰动，扰动经被控对象直接影响输出。反馈能根据输出偏差修正，扰动前馈能在已知模型下预先补偿，复合控制结合两种通道。这里比较的是题干限定的结构能力，不能离开控制器设计和扰动位置，对任意系统作数值大小的绝对排序。','建模 / 基本概念')
q(17,'南京工业大学 2025','57','107–108',r'单位负反馈开环 $G=K/[s(Ts+1)]$，零初值，单位阶跃误差 $e(t)=2e^{-2t}-e^{-4t}$。求 $K$。',
 ['$3/2$','$2/3$','$4/3$','$3/4$'],'C。$K=4/3$。',
 r'对误差变换得 $E=2/(s+2)-1/(s+4)=(s+6)/(s^2+6s+8)$。另一方面 $E=(Ts+1)/(Ts^2+s+K)$。将后一式分子分母同除以 $T$，比较分子常数得 $1/T=6$，再比较分母常数得 $K/T=8$。因此 $T=1/6$、$K=4/3$。','时域分析 / 反求参数')
q(18,'南京工业大学 2025','57','108',r'单位负反馈开环 $G=16/[s(s+4)]$，闭环属于哪类典型二阶系统？',
 ['过阻尼','无阻尼','欠阻尼','临界阻尼'],'C。',
 r'闭环分母 $s^2+4s+16$。与 $s^2+2\zeta\omega_ns+\omega_n^2$ 比较得 $\omega_n=4$、$\zeta=1/2$。因 $0<\zeta<1$，极点为一对左半平面共轭复根，属于欠阻尼。','时域分析 / 二阶性能')
q(19,'南京工业大学 2025','57','108–109',r'典型欠阻尼二阶系统的超调量主要刻画哪项动态性能？',
 ['快速性','平稳性','精确性','准确性'],'B。',
 r'相对超调量为首次峰值超过终值的百分比，衡量过渡过程对目标值的越过程度，属于平稳性指标。典型二阶模型中 $\sigma=\exp[-\pi\zeta/\sqrt{1-\zeta^2}]$；阻尼比越大，超调越小。快速性通常用上升、峰值和调节时间描述，稳态准确性用稳态误差描述。','时域分析 / 二阶性能')
rr,count=routh([1,4,-4,4,-7,-8,10]);assert count==2
q(20,'青岛大学 2025','57','109',r'特征方程 $s^6+4s^5-4s^4+4s^3-7s^2-8s+10=0$，右半平面极点数为：',
 ['0','1','2','3'],'C。2 个。',rr,'时域分析 / 劳斯稳定')
q(21,'北京科技大学 2025','57','109',r'高阶稳定系统的闭环主导极点向虚轴靠近，且主导关系和留数无显著变化，响应衰减速度：',
 ['越快','越慢','不变','只由输入幅度决定'],'B。',r'主导极点对应的模态衰减包络为 $e^{-at}$，其中 $a$ 为极点负实部的绝对值。向虚轴靠近使 $a$ 变小、衰减变慢，常用调节时间也随之增大。','时域分析 / 主导极点')
q(22,'长沙理工大学 2025','57','109',r'无零点的典型二阶系统，闭环特征根为一对相等的负实根，属于：',
 ['欠阻尼','过阻尼','临界阻尼','无阻尼'],'C。',r'标准特征方程为 $s^2+2\zeta\omega_ns+\omega_n^2=0$。负实重根要求判别式为零且根为负，因此 $\zeta=1$、$\omega_n>0$，即临界阻尼。单位阶跃响应为 $1-(1+\omega_nt)e^{-\omega_nt}$，无振荡。','时域分析 / 二阶性能')
q(23,'长沙理工大学 2025','58','109–110',r'单位负反馈闭环 $\Phi=(s+2)/(s^2+6s+5)$。下列说法不正确的是：',
 ['闭环静态增益为 1','分母对应过阻尼','闭环稳定','开环零点为 $-2$'],'A。闭环静态增益为 $2/5$。',
 r'由 $\Phi(0)=2/5$，A 错。分母 $(s+1)(s+5)$ 两根均为负实根，对应 $\zeta=3/\sqrt5>1$，B、C 正确。开环 $G=\Phi/(1-\Phi)=(s+2)/(s^2+5s+3)$，其零点确为 $-2$，D 正确。含零点时不能直接套无零点二阶系统的全部时域指标公式。','时域分析 / 二阶性能')
q(24,'北京科技大学 2022','58','110',r'开环 $G=40/[(2s+1)(s+4)]$，写成时间常数形式后，开环增益为：',
 ['40','20','10','4'],'C。10。',r'提取第二个因子的常数 $4$，得 $G=10/[(2s+1)(0.25s+1)]$，所以开环增益为 $10$。该系统没有积分器，开环静态增益也等于 $G(0)=10$。','建模 / 传递函数')
q(25,'北京科技大学 2024','58','110',r'在不破坏闭环稳定性、积分器未被相消的前提下，以下哪种措施单独加入时通常不能改善多项式输入的稳态精度？',
 ['增加积分作用','增大正的开环增益','仅增加理想微分作用','引入准确的扰动补偿'],'C。',r'积分器能提高系统型别，增益增大可提高有限误差系数，正确的扰动补偿可减小对应扰动误差。纯微分作用在零频处增益为零，单独依靠微分不能提高低频误差系数；它主要用于改变动态响应。实际加积分或增益时仍须先检查稳定性。','时域分析 / 稳态误差')
q(26,'中国矿业大学 2023','58','110–111',r'以下描述中，哪项对应稳定的因果线性定常输入输出系统？C 项按零初值单位阶跃响应理解，并允许直接传递。',
 [r'闭环极点 $0.5\pm3j$',r'特征多项式 $s^3+0.5s^2+4s+20$',r'阶跃响应 $c(t)=10(1+e^{-t})\,1(t)$',r'特征多项式 $s^2-0.1s+2$'],'C。',
 r'A 的极点实部为正；B 的三阶劳斯条件 $0.5\times4>20$ 不成立；D 的根实部为 $0.05>0$。C 对应 $\Phi=s[10/s+10/(s+1)]=10(s+2)/(s+1)$，唯一极点为 $-1$，且可有直接传递项 $10$，所以输入输出稳定。其阶跃起始值非零不会自动导致不稳定。','时域分析 / 稳定性')
q(27,'中国矿业大学 2023','58','111',r'开环 $G(s)H(s)=10(s+3)/[s(s+1)(s+5)]$，静态位置误差系数 $K_p$ 为：',
 ['10','30',r'$\infty$','6'],'C。',r'$K_p=\lim_{s\to0}G(s)H(s)$。分母有一个未相消原点极点，分子在原点非零，因此正向低频极限趋于正无穷。若还要求单位阶跃零稳态误差，须另行保证闭环稳定，不能把误差系数的形式极限直接等同于实际终值。','时域分析 / 稳态误差')
q(28,'中国矿业大学 2023','58–59','111',r'闭环 $G=100(s+10.5)/[(s+100)(s^2+2s+4)]$，按主导二阶极点并保留直流增益降阶，可近似为：',
 [r'$10.5/(s^2+2s+4)$',r'$10/(s^2+2s+4)$',r'$100(s+10.5)/(s+10)$',r'$25(s+10.5)/(s+10)$'],'A。',r'主导极点为 $-1\pm j\sqrt3$，极点 $-100$ 为快极点。低频下 $(s+10.5)/(s+100)\approx10.5/100$，因此保留二阶分母后分子为 $10.5$。原直流增益为 $100\times10.5/(100\times4)=2.625$，降阶后仍为 $10.5/4=2.625$。','时域分析 / 主导极点')
q(29,'中国矿业大学 2023','59','111',r'闭环 $\Phi_1=4/[(s^2+2s+4)(10s+1)]$，$\Phi_2=4/(s^2+2s+4)$。零初值单位阶跃下，正确的是：',
 [r'$\Phi_1$ 的超调量更大',r'$\Phi_1$ 的稳态值更大',r'$\Phi_2$ 的超调量更大',r'$\Phi_2$ 的稳态值更大'],'C。',
 r'两者直流增益均为 $1$，故稳态值相同。$\Phi_2$ 为 $\zeta=0.5$ 的典型二阶系统，超调约 $16.30\%$。$\Phi_1$ 在其后串联慢一阶环节 $1/(10s+1)$，阶跃响应为对 $\Phi_2$ 阶跃响应作正权指数平均，任何有限时刻的值都小于后者的全局最大值，因此其正超调更小。这里对具体串联系统作判断，不泛化为“增加任何极点都能减小超调”。','时域分析 / 二阶性能')
q(30,'杭州电子科技大学 2021','59','111',r'单位负反馈开环 $G=10/[s(s+2)]$，输入 $r(t)=(2+5t)1(t)$。求稳态误差。',
 ['0',r'$\infty$','1','2'],'C。1。',r'闭环分母 $s^2+2s+10$ 稳定。系统为 I 型，阶跃分量误差为零，速度误差系数 $K_v=5$，斜坡分量误差为 $5/K_v=1$。输入 $5t$ 的拉氏变换为 $5/s^2$，不能遗漏斜率系数。','时域分析 / 稳态误差')
q(31,'杭州电子科技大学 2023','59','111',r'二阶系统 $G=5/(s^2+2s+5)$ 属于：',
 ['临界阻尼','欠阻尼','过阻尼','无阻尼'],'B。',r'与标准二阶分母比较，$\omega_n=\sqrt5$，$\zeta=1/\sqrt5$，在 $0$ 与 $1$ 之间。也可直接求根为 $-1\pm2j$，是一对左半平面共轭复根，因此欠阻尼。','时域分析 / 二阶性能')
q(32,'杭州电子科技大学 2024','59–60','111',r'单位负反馈系统的前向环节为 $1/s$。将反馈通道断开，零初值，输入为单位阶跃，输出为：',
 ['0',r'$\delta(t)$',r'$1(t)$',r'$t1(t)$'],'D。',r'断开反馈后输入直接作用于积分环节，$C(s)=R(s)/s=1/s^2$。反变换得到 $c(t)=t1(t)$。若反馈保持闭合，则传递函数为 $1/(s+1)$，响应不同；应按题干断开后的连接求解。','时域分析 / 响应计算')

f(1,'北京科技大学 2025','60','111',r'零初值闭环 $G=5/(s+2)$，求单位阶跃响应在 $t=0^+$ 的切线斜率。','5。',r'$C=5/[s(s+2)]$，反变换 $c(t)=\frac52(1-e^{-2t})$，导数 $\dot c=5e^{-2t}$，所以 $\dot c(0^+)=5$。也可用 $\dot c(0^+)=\lim_{s\to\infty}sG(s)$ 验证。')
f(2,'北京科技大学 2025','60','112',r'典型二阶系统的单位阶跃响应为等幅振荡，求阻尼比。',r'$\zeta=0$。',r'标准二阶极点为 $-\zeta\omega_n\pm j\omega_n\sqrt{1-\zeta^2}$。振幅既不衰减也不增长要求实部为零，因此 $\zeta=0$。此时阶跃响应 $1-\cos\omega_nt$，为无阻尼振荡。','时域分析 / 二阶性能')
f(3,'北京科技大学 2025','60','112',r'单位负反馈系统零状态单位脉冲响应为 $g(t)=(e^{-3t}+2e^{-t})1(t)$，求开环传递函数。',
 r'$$G=\frac{3s+7}{s^2+s-4}.$$ ',r'脉冲响应的拉氏变换即闭环传递函数 $\Phi=1/(s+3)+2/(s+1)=(3s+7)/(s^2+4s+3)$。由单位负反馈关系 $G=\Phi/(1-\Phi)$，通分得分母 $s^2+s-4$。闭环稳定与开环有右半平面极点不矛盾。','时域分析 / 反求参数')
f(4,'海南大学 2025','60','112',r'某稳定零极点对的间距远小于各自到原点的距离，这样的近邻零极点对称为什么？','偶极子（近似相消的零极点对）。',r'若零点 $z$ 与极点 $p$ 接近，因子 $(s-z)/(s-p)=1+(p-z)/(s-p)$。当两者距离相对其模长很小时，相关模态的留数通常较小，可在适用频段近似相消。精确相消和近似相消不同，右半平面或虚轴极点不能凭相消外观就认定内部稳定。','时域分析 / 主导极点')
rr,count=routh([1,2,8,12,2,16,16]);assert count==2
f(5,'合肥工业大学 2025','60','112',r'特征多项式 $D=s^6+2s^5+8s^4+12s^3+2s^2+16s+16$。用劳斯判据求右半平面极点个数。','2 个。',
 rr+r'\n\n辅助多项式为 $2s^4-6s^2+16$，对称根结构不等于全为纯虚根。应完成导数替换和后续首列判号。','时域分析 / 劳斯稳定','对照8月勘误第5页：更正表按题本常数16计算，首列1,2,2,8,-6,48,16；勘误正文的D(s)仍残留常数6，与更正表不一致，本卡采用题本及更正表。')
f(6,'合肥工业大学 2025','60','113',r'单位负反馈开环 $G=4/[s(s+5)]$，求零状态单位脉冲响应。',
 r'$$g(t)=\frac43(e^{-t}-e^{-4t})1(t).$$',r'闭环 $\Phi=4/(s^2+5s+4)=4/[(s+1)(s+4)]$。脉冲输入的变换为 $1$，所以输出变换即 $\Phi$。部分分式分解为 $(4/3)[1/(s+1)-1/(s+4)]$，反变换即得。')
f(7,'合肥工业大学 2025','61','113',r'零初值，$2.5\dot c+c=50r$，求单位阶跃响应。',r'$c(t)=50(1-e^{-0.4t})1(t)$。',r'传递函数 $50/(2.5s+1)$，时间常数 $T=2.5$，静态增益 $50$。阶跃输出变换为 $50/[s(2.5s+1)]=50/s-50/(s+0.4)$，反变换即可。响应初值为0，终值为50。')
f(8,'昆明理工大学 2025','61','114',r'一阶系统 $1/(1+Ts)$，$T>0$，初值为零，求单位阶跃响应。',r'$c(t)=(1-e^{-t/T})1(t)$。',r'输出变换为 $1/[s(1+Ts)]=1/s-1/(s+1/T)$。反变换得到答案；$t=T$ 时达到终值的 $1-e^{-1}\approx63.2\%$，可用于检查时间常数。','时域分析 / 一阶响应')
f(9,'昆明理工大学 2025','61','114',r'单位负反馈开环 $G=K/[s(s^2+3s+2)]$，$K>0$。求从稳定区达到临界振荡时的 $K$。',r'$K=6$，振荡频率 $\sqrt2\,\mathrm{rad/s}$。',r'闭环分母 $s^3+3s^2+2s+K$。劳斯首列 $1,3,(6-K)/3,K$，稳定范围 $0<K<6$。在 $K=6$ 时，分母为 $(s+3)(s^2+2)$，出现简单虚根 $\pm j\sqrt2$。','时域分析 / 劳斯稳定')
rr,count=routh([1,2,10,0,1]);assert count==2
f(10,'昆明理工大学 2025','61','114–115',r'单位负反馈开环 $G=1/[s^2(s^2+2s+10)]$，输入 $r(t)=(2+4t+4t^2)1(t)$。先判稳，再讨论实际稳态误差。',
 '闭环不稳定，实际稳态误差不存在。',rr+r'\n\n闭环特征多项式为 $s^4+2s^3+10s^2+1$，有两个右半平面极点。虽然形式上 $K_a=\lim s^2G=1/10$，但不能把 $8/K_a=80$ 当成实际稳态误差，因为终值定理的稳定性条件不满足。','时域分析 / 稳态误差','8月勘误未列此项；增加先判稳要求，修正答案册忽略闭环不稳定而套误差系数的问题。')
f(11,'昆明理工大学 2025','61','115',r'零状态单位脉冲响应 $g(t)=(e^{-0.2t}+3e^{-2t})1(t)$，求闭环传递函数。',
 r'$$\Phi=\frac1{s+0.2}+\frac3{s+2}=\frac{4s+2.6}{s^2+2.2s+0.4}.$$ ',r'单位脉冲的拉氏变换为1，故传递函数等于脉冲响应的拉氏变换。分别对指数项变换后相加，再乘以共同分母整理。这里已给闭环脉冲响应，不需要再套 $G/(1+G)$。')
f(12,'昆明理工大学 2025','61','115',r'闭环 $\Phi=2(0.49s+1)/[(0.125s+1)(0.5s+1)(s^2+s+1)]$，按主导极点降阶并保留直流增益。',
 r'$$\Phi_{red}\approx\frac2{s^2+s+1}.$$ ',r'零点约为 $-2.0408$，与极点 $-2$ 接近，形成偶极子；另有快极点 $-8$。主导极点为 $-0.5\pm j\sqrt3/2$。先近似相消接近的因子，再将快环节 $1/(0.125s+1)$ 按低频增益1处理，即得答案。原、降阶模型的直流增益均为2。','时域分析 / 主导极点')
f(13,'长沙理工大学 2025','61','115',r'开环 $G=20(s+1)/[s(s+10)]$。求惯性环节时间常数，指出 $s+1$ 的环节类型，并求时间常数形式的开环增益。',
 r'$T=0.1\,\mathrm s$；一阶微分（比例微分）环节；$K=2$。',r'将 $s+10=10(0.1s+1)$，得 $G=2(s+1)/[s(0.1s+1)]$。因此惯性时间常数为0.1，一阶分子 $s+1$ 是比例与微分并联形成的一阶微分环节，系统型别为I型，开环增益为2。','建模 / 传递函数')
f(14,'浙江理工大学 2025','62','116',r'单位负反馈前向环节 $G=(1+1/s)K/[s(s+3)(s+6)]$，$K>0$。输入 $r=t^2\,1(t)$，求闭环稳定且 $e_{ss}\le0.5$ 的 $K$ 范围。',
 '$72\\le K<81$。','闭环特征多项式为 $s^4+9s^3+18s^2+Ks+K$。劳斯首列为\n$$1,\\quad9,\\quad\\frac{162-K}{9},\\quad\\frac{K(81-K)}{162-K},\\quad K.$$\n首列同正得到 $0<K<81$。输入 $r=t^2$ 的变换为 $2/s^3$，系统为 II 型，$K_a=\\lim s^2G=K/18$，因此 $e_{ss}=2/K_a=36/K$。误差要求给出 $K\\ge72$，与稳定区相交为 $72\\le K<81$。边界81出现虚根，必须排除。','时域分析 / 稳态误差')
f(15,'浙江理工大学 2025','62','116',r'零初值单位阶跃响应 $c(t)=1+0.2e^{-60t}-1.2e^{-10t}$，$t\ge0$。求传递函数、阻尼比与自然频率（后两项保留两位小数）。',
 r'$$\Phi=\frac{600}{s^2+70s+600},\quad \zeta\approx1.43,\quad \omega_n\approx24.49\,\mathrm{rad/s}.$$ ',r'$\Phi=sC=1+0.2s/(s+60)-1.2s/(s+10)$。通分后一次项相消，得分子600。于是 $\omega_n=\sqrt{600}=10\sqrt6$，$\zeta=70/(2\sqrt{600})=7/(2\sqrt6)>1$，为过阻尼系统。','时域分析 / 反求参数')
f(16,'北京科技大学 2022','62','117',r'零状态单位脉冲响应 $h(t)=\sqrt2e^{-0.4t}\sin(t+\pi/4)\,1(t)$，求闭环传递函数。',
 r'$$\Phi=\frac{s+1.4}{s^2+0.8s+1.16}.$$ ',r'先用 $\sqrt2\sin(t+\pi/4)=\sin t+\cos t$。分别利用指数移位，得 $\Phi=1/[(s+0.4)^2+1]+(s+0.4)/[(s+0.4)^2+1]$。相加得到 $(s+1.4)/[(s+0.4)^2+1]$，展开分母即得。')
f(17,'北京科技大学 2023','62','117',r'温度计模型 $1/(Ts+1)$。水温作阶跃变化，示数需60秒才达到变化量的98%，求时间常数。',
 r'$T=60/\ln50\approx15.34\,\mathrm s$；按 $t_s\approx4T$ 估算为15秒。',r'初始示数与初始水温平衡，阶跃变化后的相对误差为 $e^{-t/T}$。由 $e^{-60/T}=0.02$ 得 $T=-60/\ln0.02$。教材的4倍时间常数为近似，不应与精确值混写。','时域分析 / 一阶响应')
f(18,'北京科技大学 2023','62','117',r'零初值单位阶跃响应 $h(t)=1-1.8e^{-4t}+0.8e^{-9t}$，$t\ge0$。求闭环频率特性。',
 r'$$\Phi(j\omega)=\frac{36}{(j\omega)^2+13j\omega+36}.$$ ',r'先求 $\Phi(s)=s[1/s-1.8/(s+4)+0.8/(s+9)]$。通分后 $s^2$、$s$ 项均相消，分子为36，分母为 $(s+4)(s+9)$。再令 $s=j\omega$ 即得闭环频率特性，而不是对时间响应直接代入 $t=j\omega$。')
f(19,'北京科技大学 2023','62–63','117',r'典型二阶系统闭环极点为 $-0.5\pm0.5j$，求无阻尼自然频率和阻尼比。',
 r'$\omega_n=\sqrt2/2\,\mathrm{rad/s}$，$\zeta=\sqrt2/2$。',r'自然频率为极点到原点的距离，$\omega_n=\sqrt{0.5^2+0.5^2}=\sqrt2/2$。阻尼比为负实部绝对值除以模长，$\zeta=0.5/(\sqrt2/2)=\sqrt2/2$。虚部0.5是阻尼振荡频率，不能当成自然频率。','时域分析 / 二阶性能')
f(20,'北京科技大学 2024','63','118',r'零状态单位脉冲响应 $h(t)=(10e^{-0.2t}+5e^{-0.5t})1(t)$，求闭环传递函数。',
 r'$$\Phi=\frac{10}{s+0.2}+\frac5{s+0.5}=\frac{15s+6}{s^2+0.7s+0.1}.$$ ',r'单位脉冲响应的拉氏变换即传递函数。通分时分子为 $10(s+0.5)+5(s+0.2)=15s+6$，分母为 $(s+0.2)(s+0.5)$。可由高频极限 $\lim s\Phi=15=h(0^+)$ 复核。')
f(21,'北京科技大学 2024','63','118',r'开环 $G=8(s+0.1)/[s(s^2+s+1)(s^2+s+25)]$，求时间常数形式的开环增益。',
 r'$K=0.032$。',r'将分子写为 $0.8(10s+1)$，第二个二阶因子写为 $25(0.04s^2+0.04s+1)$，第一个二阶因子的常数已为1。因此常数系数为 $0.8/25=0.032$。此处有积分器，开环直流值发散，所问“开环增益”指标准时间常数形式中的常数。','建模 / 传递函数')
f(22,'江南大学 2024','63','118',r'零初值一阶系统的单位阶跃响应终值为1，在 $t=20\,\mathrm s$ 首次达到0.98。求闭环传递函数，并给工程近似。',
 r'$$\Phi(s)=\frac1{(20/\ln50)s+1}\approx\frac1{5.113s+1}.$$ 工程近似为 $1/(5s+1)$。',r'一阶响应 $c=1-e^{-t/T}$。由 $1-e^{-20/T}=0.98$ 得 $T=20/\ln50\approx5.113$ 秒。用2%调节时间 $t_s\approx4T$ 才得到 $T\approx5$ 秒，两种写法应注明精确或近似。','时域分析 / 一阶响应')
f(23,'合肥工业大学 2024','63','118',r'零初值闭环 $\Phi=10/(s+5)$，以终值的5%为误差带，求调节时间。',
 r'$t_s=\ln20/5\approx0.5991\,\mathrm s$；工程近似0.6秒。',r'单位阶跃终值为2，响应为 $2(1-e^{-5t})$。相对终值误差为 $e^{-5t}$，令其等于0.05即可。采用相对误差带，静态增益2不会使调节时间加倍。','时域分析 / 一阶响应')
f(24,'合肥工业大学 2024','63','118',r'单位负反馈开环 $G=K/[s(s+10)]$，要求阻尼比 $\zeta=0.5$，求 $K$。',
 r'$K=100$。',r'闭环分母 $s^2+10s+K$，比较得 $\omega_n=\sqrt K$、$2\zeta\omega_n=10$。代入 $\zeta=0.5$ 得 $\omega_n=10$，故 $K=100$。','时域分析 / 二阶性能')
rr,count=routh([1,3,-3,-9,-4,12]);assert count==2
f(25,'合肥工业大学 2024','63–64','118–119',r'$D=s^5+3s^4-3s^3-9s^2-4s+12$，用劳斯判据求右半平面根数。','2 个。',rr,'时域分析 / 劳斯稳定')
f(26,'中国矿业大学 2024','64','119',r'闭环 $\Phi=150(s+3.1)/[(s+10)(s+3)(s^2+2s+6)]$，降为保持直流增益的主导二阶模型。',
 r'$$\Phi_{red}=\frac{15.5}{s^2+2s+6}.$$ ',r'零点 $-3.1$ 与极点 $-3$ 近邻，$-10$ 为快极点，主导极点为 $-1\pm j\sqrt5$。令降阶分子为 $b$，原直流增益为 $150\cdot3.1/(10\cdot3\cdot6)=31/12$，故 $b/6=31/12$，得到 $b=15.5$。直接把近邻因子严格相消会给15并改变直流增益。','时域分析 / 主导极点')
f(27,'中国矿业大学 2024','64','119',r'单位负反馈系统闭环 $\Phi=4/(s^2+2s+6)$，零初值单位阶跃下求位置稳态误差。',
 r'$e_{ss}=1/3$。',r'分母两根实部为负，闭环稳定。输出终值为 $\Phi(0)=4/6=2/3$，误差 $e=r-c$ 的终值为 $1-2/3=1/3$。题给是闭环函数，若错误套成 $1/(1+\Phi(0))$ 会得到不正确的值。','时域分析 / 稳态误差')
f(28,'中国矿业大学 2024','64','119',r'负反馈开环乘积 $GH=(\tau s+1)/[s^2(Ts+1)]$，$T>0$。求闭环渐近稳定条件。',
 r'$\tau>T>0$。',r'特征多项式为 $Ts^3+s^2+\tau s+1$。劳斯首列为 $T,1,\tau-T,1$。在 $T>0$ 前提下，同正等价于 $\tau>T$。若 $\tau=T$，则 $(Ts+1)(s^2+1)$ 出现虚根，属于临界而非渐近稳定。','时域分析 / 劳斯稳定')
f(29,'杭州电子科技大学 2023','64','119',r'二阶闭环 $\Phi=4/(s^2+2s+4)$，求无阻尼自然频率。',
 r'$\omega_n=2\,\mathrm{rad/s}$。',r'与标准分母 $s^2+2\zeta\omega_ns+\omega_n^2$ 比较，常数项给出 $\omega_n^2=4$，所以 $\omega_n=2$。其实际振荡频率为 $\omega_d=\sqrt3$，与自然频率不同。','时域分析 / 二阶性能')
f(30,'杭州电子科技大学 2023','64','119',r'典型二阶系统的稳定共轭极点位于哪两条从原点出发的射线上时，阻尼比为 $1/\sqrt2\approx0.707$？角度由正实轴逆时针计。',
 r'$135^\circ$ 与 $225^\circ$（等价于与负实轴夹角 $\pm45^\circ$）。',r'稳定复极点 $s=-\zeta\omega_n\pm j\omega_n\sqrt{1-\zeta^2}$。当 $\zeta=1/\sqrt2$ 时，实部绝对值与虚部绝对值相等，所以在左半平面的两条45度射线上。若从正实轴计角，必须写135和225度。','时域分析 / 二阶性能')
f(31,'杭州电子科技大学 2023','64','119',r'稳定系统的快速性主要由主导极点决定时，主导极点距虚轴越远还是越近，模态衰减越快？',
 '越远。',r'左半平面极点为 $-a+jb$，衰减因子 $e^{-at}$。距虚轴越远表示 $a$ 越大，达到同一误差包络所需时间越短。该结论限定主导极点且忽略零点留数变化，不意味着任意移动非主导极点都能改善全过程。','时域分析 / 主导极点')

j(1,'杭州电子科技大学 2015','64','120','零状态因果 LTI 系统的传递函数的拉氏反变换是单位脉冲响应。','正确。',r'零初值下 $Y=G(s)U$，单位脉冲输入 $U=1$，输出变换为 $Y=G$，故 $g(t)=\mathcal L^{-1}\{G\}$。如存在直接传递，脉冲响应中会包含相应的 $\delta(t)$ 项。')
j(2,'杭州电子科技大学 2015','64','120','复合控制的两种基本形式是按给定输入的前馈加反馈、按扰动的前馈加反馈。','正确。',r'给定前馈利用已知参考改善跟踪；扰动前馈利用可测扰动补偿其影响。反馈通道仍根据输出偏差修正建模误差和未测扰动，因此二者都属于前馈与反馈组成的复合结构。')
j(3,'杭州电子科技大学 2016','64','120','典型欠阻尼二阶系统保持阻尼比不变，减小自然频率，将增大上升时间和峰值时间。','正确。',r'$t_p=\pi/[\omega_n\sqrt{1-\zeta^2}]$；首次达到终值的上升时间为 $t_r=(\pi-\arccos\zeta)/[\omega_n\sqrt{1-\zeta^2}]$。固定 $0<\zeta<1$ 时，两者均与 $\omega_n$ 成反比。')
j(4,'杭州电子科技大学 2016','65','120','过阻尼典型二阶系统因为存在振荡而反应迟钝。','错误。',r'过阻尼时 $\zeta>1$，两个极点为相异负实根，无复共轭振荡模态。其迟钝通常由较慢实极点造成。典型无零点阶跃响应单调逼近终值，不能把响应慢归因于振荡。')
j(5,'中国科学技术大学 2012','65','120','自然频率为正的临界阻尼典型二阶系统是渐近稳定系统。','正确。',r'$\zeta=1$ 时特征式 $(s+\omega_n)^2$，重根位于负实轴。自然响应为 $(a+bt)e^{-\omega_nt}$，当 $\omega_n>0$ 时仍趋于零，因此稳定。负实重根不会像虚轴重根那样引起不衰减或增长。')
j(6,'中国科学技术大学 2012','65','120','典型欠阻尼二阶系统保持阻尼比不变，增大自然频率会缩短过渡过程并增大相对超调量。','错误。',r'固定 $\zeta$ 时，上升、峰值及调节时间按 $1/\omega_n$ 缩短，但相对超调量 $\sigma=e^{-\pi\zeta/\sqrt{1-\zeta^2}}$ 只取决于阻尼比，不随 $\omega_n$ 改变。前半句正确，后半句错误。')
j(7,'同济大学 2019','65','120','稳定0型单位负反馈系统，只需把有限的正静态增益取得足够大，就能使单位阶跃稳态误差严格为零。','错误。',r'误差为 $e_{ss}=1/(1+K_p)$。任意有限 $K_p>0$ 时该值仍大于零，只能在 $K_p\to\infty$ 的形式极限下趋于零。实际增益还受稳定性、噪声和饱和约束，严格无差通常需积分内模。')
j(8,'同济大学 2019','65','120','渐近稳定 LTI 系统在同一给定输入下，初始状态只影响会衰减的暂态部分，不改变最终稳态部分。','正确。',r'两个不同初值但相同输入的状态差满足 $\delta x(t)=e^{At}\delta x(0)$。$A$ 渐近稳定时该差趋于零，所以初值不影响最终稳态。题干明确渐近稳定，避免把含积分器或无阻尼模态的系统也套入此结论。')
j(9,'中南大学 2025','65','120','线性定常系统齐次运动的稳定性由系统本身决定；非线性系统的局部稳定性可能依赖平衡点及初始状态所在区域。','正确。',r'对 LTI 系统，内部渐近稳定等价于状态矩阵全部特征值具有负实部，不由某次初值或输入幅值改变。对非线性系统，同一系统不同平衡点可有不同局部稳定性，吸引域也可有限。讨论受迫非线性轨道时还需指定输入和参考运动，不能把所有稳定性定义混为一谈。')
j(10,'中南大学 2025','65','120','一个渐近稳定 LTI 系统，在零初值单位阶跃输入下，输出一定逐渐收敛到零。','错误。',r'稳定保证自然响应衰减，阶跃引起的强迫稳态一般为 $G(0)$，不必为零。例如 $G=1/(s+1)$ 的单位阶跃响应为 $1-e^{-t}$，终值为1。只有相应直流增益为零时才可能阶跃终值为零。')
j(11,'南京邮电大学 2025','65','120','LTI 闭环内部自然运动的模态由闭环极点决定。','正确。',r'若闭环矩阵有特征值 $\lambda_i$，状态自然响应由 $e^{\lambda_it}$ 及重根对应的 $t^ke^{\lambda_it}$ 组成。极点决定指数和振荡形式，初值、输入和零点决定各模态在给定输出中的系数；某些内部模态可能在非最小输入输出传递函数中被隐藏。')

sh(1,'浙江理工大学 2025','65–66','121',r'单位负反馈前向 $G=1/[s(s+1)]$，零初值单位阶跃输入。稳态时 $e\to0$，为何积分环节的输出仍可保持 $c\to1$？',
 '积分环节存储了过渡过程中的累积状态，零输入只表示其状态不再变化，并不强制其状态为零。',r'由 $C=E/[s(s+1)]$ 得时域方程 $\ddot c+\dot c=e$。稳态时 $\dot c=\ddot c=0$，所以可以同时满足 $e=0$、$c=1$。也可从内部积分状态理解：积分器输出等于初值加误差信号的历史积分；误差最终变零以后，历史累积值继续保留。整个闭环特征式 $s^2+s+1$ 稳定，且 $\Phi(0)=1$。')
sh(2,'西安理工大学 2025','66','121','简述闭环主导极点的定义及使用主导极点降阶时应检查的条件。',
 '在系统实际响应中，对主要过渡过程贡献最大的闭环极点称为主导极点；稳定系统中通常为衰减较慢、且未被近邻零点削弱的极点。',r'简单极点 $p_i$ 的模态为 $a_ie^{p_it}$。负实部绝对值较小的极点衰减较慢，但若留数 $a_i$ 极小，它未必主导。因此降阶应同时检查与其他极点的分离程度、附近零点及模态留数，并保持适合任务的低频或直流特性。其他极点距虚轴约五倍以上是常用经验，不是普适定理。')
sh(3,'西安理工大学 2025','66','121','说明闭环极点分布与单位阶跃响应的关系。',
 '极点的实部决定衰减或增长，虚部决定振荡频率，重数决定是否带多项式因子；零点和留数还影响各模态的幅值与组合。',r'负实极点产生衰减指数，左半平面共轭复极点产生衰减振荡；越靠近虚轴的显著模态一般衰减越慢。正实部极点产生增长模态。简单虚轴极点可产生不衰减振荡，虚轴重极点可能产生随时间增长的项。典型二阶系统可由极点的模长、与负实轴夹角得到 $\omega_n,\zeta$；高阶或含零点系统不能仅凭极点套用所有典型二阶指标。')
sh(4,'中国民航大学 2025','66','121',r'对 $\omega_n>0$ 的标准二阶特征式 $s^2+2\zeta\omega_ns+\omega_n^2$，分别讨论 $\zeta>1$、$0<\zeta<1$、$\zeta=1$、$\zeta=0$、$-1<\zeta<0$ 的特点。',
 '依次为过阻尼稳定、欠阻尼稳定、临界阻尼稳定、无阻尼临界振荡、负阻尼不稳定。',r'根为 $-\zeta\omega_n\pm\omega_n\sqrt{\zeta^2-1}$。$\zeta>1$ 为两个相异负实根；$0<\zeta<1$ 为左半平面共轭复根；$\zeta=1$ 为负实重根；$\zeta=0$ 为简单纯虚根；$-1<\zeta<0$ 的共轭根实部为正，振幅指数增长。过阻尼与临界阻尼的典型无零点阶跃响应无超调，欠阻尼有衰减振荡。')

